 *          path[i][j] = 999;
 *     }
 *
 * C array path[i][j] is mapped to Buffer(j, i).
 */
static void init_array(int n, Buffer<num_t, 2> path) {
    Var i("i"), j("j");
    Func init_path("init_path");

    // Base value: i * j % 7 + 1  (computed in 32-bit int then cast)
    Expr base = cast<num_t>((i * j % 7) + 1);

    // Condition for setting to 999
    Expr sum = i + j;
    Expr cond = ((sum % 13) == 0) ||
                ((sum % 7)  == 0) ||
                ((sum % 11) == 0);

    init_path(j, i) = select(cond,
                             cast<num_t>(Expr(999)),
                             base);

    // ------------------------------------------------------------------
    // Schedule for initialization
    //
    // Memory layout: Buffer(j, i) is row-major in j (columns) for each i.
    // We therefore:
    //   - vectorize across j (fast-varying dim)
    //   - parallelize across tiles of i (rows)
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int tile_i    = 64;  // rows per parallel task

    Var io("io"), ii("ii"), jo("jo"), ji("ji");

    init_path
        // Tile in i to create coarse-grain tasks.
        .split(i, io, ii, tile_i)
        // Split j for vectorization.
        .split(j, jo, ji, std::max(1, vec_width))
        // j-inner, then i-inner, then tile indices.
        .reorder(ji, jo, ii, io)
        // SIMD across contiguous j.
        .vectorize(ji)
        // Parallelize across row-tiles.
        .parallel(io);

    // Realize into the provided buffer. Buffer layout is (x=j, y=i).
    init_path.realize(path);
}

