    Param<int> k_param("k");

    Var i("i"), j("j");
    Func floyd_step("floyd_step");

    // Mapping of the original C indices to Halide coordinates:
    //   C: path[i][j] -> path_param(j, i)
    //   C: path[i][k] -> path_param(k, i)   (column index = k)
    //   C: path[k][j] -> path_param(j, k)   (row index    = k)
    Expr current = path_param(j, i);
    Expr via_k   = path_param(k_param, i) + path_param(j, k_param);

    floyd_step(j, i) = Halide::min(current, via_k);

    // ------------------------------------------------------------------
    // Schedule for a single Floyd–Warshall step
    //
    // - j is the fast-varying (contiguous) dimension, so we vectorize it.
    // - i is the slow dimension; we tile it and parallelize across tiles.
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(path_param.type());
    const int tile_i    = 64;  // rows per parallel task

    Var io("io"), ii("ii"), jo("jo"), ji("ji");

    floyd_step
        // Tile rows (i) to create coarse-grain parallel tasks.
        .split(i, io, ii, tile_i)
        // Split columns (j) for SIMD.
        .split(j, jo, ji, std::max(1, vec_width))
        // Inner loops: ji (SIMD over j), then jo, ii, io.
        .reorder(ji, jo, ii, io)
        // Vectorize along contiguous j.
        .vectorize(ji)
        // Parallelize across row tiles.
        .parallel(io);

    // Bind initial data and compile the step once.
    path_param.set(path0);
    k_param.set(0); // will be updated inside the loop
    floyd_step.compile_jit(target);

    // Double-buffering pointers
    Buffer<num_t, 2> *current_path = &path0;
    Buffer<num_t, 2> *next_path    = &path1;

    // Time only the Floyd–Warshall kernel (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 0; k < n; k++) {
        // Bind the current path and the iteration index k
        path_param.set(*current_path);
        k_param.set(k);

        // Compute the next path
        floyd_step.realize(*next_path);

        // Swap buffers for the next iteration
        std::swap(current_path, next_path);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // The final result is in *current_path
    Buffer<num_t, 2> &path = *current_path;

